WITH lines AS (SELECT id, plan, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) x AS tier_value) SELECT id, plan, currency, tier_value, CUME_DIST() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_cume_dist, STDDEV_SAMP(tier_value) OVER (PARTITION BY currency) AS currency_stddev_samp_tier_value, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_percent_rank, COUNT(tier_value) OVER (PARTITION BY plan, currency) AS plan_count_tier_value, AVG(tier_value) OVER (PARTITION BY plan, currency) AS plan_avg_tier_value FROM lines;
